public void testBitVectorClassBindingsDotProduct() throws IOException {
    String fieldName = "vector";
    int dims = 8;
    float[] docVector = new float[]{124}; // 124 in binary is b01111100
    List<Number> byteQueryVector = Arrays.asList((byte) 1, (byte) 125, (byte) -12, (byte) 2, (byte) 4, (byte) 1, (byte) 125, (byte) -12);
    List<Number> floatQueryVector = Arrays.asList(1.4f, -1.4f, 0.42f, 0.0f, 1f, -1f, -0.42f, 1.2f);
    List<Number> invalidQueryVector = Arrays.asList((byte) 1, (byte) 1);
    String hexidecimalString = HexFormat.of().formatHex(new byte[]{124});
    List<DenseVectorDocValuesField> fields = List.of(
        new BitBinaryDenseVectorDocValuesField(BinaryDenseVectorScriptDocValuesTests.wrap(new float[][]{docVector}, ElementType.BIT, IndexVersion.current()), "test", ElementType.BIT, dims),
        new BitKnnDenseVectorDocValuesField(KnnDenseVectorScriptDocValuesTests.wrapBytes(new float[][]{docVector}), "test", dims)
    );
    for (DenseVectorDocValuesField field : fields) {
        field.setNextDocId(0);
        ScoreScript scoreScript = mock(ScoreScript.class);
        when(scoreScript.field(fieldName)).thenAnswer(mock -> field);
        DotProduct byteDotProductFunction = new DotProduct(scoreScript, byteQueryVector, fieldName);
        assertEquals("dotProduct result is not equal to the expected value!", -12 + 2 + 4 + 1 + 125, byteDotProductFunction.dotProduct(), 0.001);
        DotProduct floatDotProductFunction = new DotProduct(scoreScript, floatQueryVector, fieldName);
        assertEquals("dotProduct result is not equal to the expected value!", 0.42f + 0f + 1f - 1f - 0.42f, floatDotProductFunction.dotProduct(), 0.001);
        DotProduct hexStringDotProductFunction = new DotProduct(scoreScript, hexidecimalString, fieldName);
        assertEquals("dotProduct result is not equal to the expected value!", Integer.bitCount(124), hexStringDotProductFunction.dotProduct(), 0.0);
        IllegalArgumentException e = expectThrows(IllegalArgumentException.class, () -> new DotProduct(scoreScript, invalidQueryVector, fieldName));
        assertThat(e.getMessage(), containsString("query vector has an incorrect number of dimensions. Must be [1] for bitwise operations, or [8] for byte wise operations: provided [2]."));
    }
}
